-- Response playbooks
INSERT INTO response_playbooks (playbook_id, name, description, signal_type, steps, created_by)
  VALUES ('be030c71-b1b9-4f85-a886-cee5e1a1138b', 'Suspicious death scene response', 'Secure the scene, notify police and the forensic pathologist, preserve evidence before body removal.', 'suspicious_death', '["Secure the scene and restrict access","Notify the nearest police post","Dispatch forensic team for scene examination","Document the scene (photos, body position, witnesses)","Arrange body removal to the mortuary","Open a case investigation and link it to the signal"]'::jsonb, (SELECT user_id FROM users WHERE email = 't.moyo@mohcc.org.zw'))
  ON CONFLICT (playbook_id) DO NOTHING;
INSERT INTO response_playbooks (playbook_id, name, description, signal_type, steps, created_by)
  VALUES ('ee118f66-1066-48f2-80f8-3f71005dddb3', 'MPDSR community verification', 'Verify a suspected maternal or perinatal death within 48 hours and open an MPDSR review.', 'maternal_perinatal', '["Contact the reporting source to confirm the death","Verify pregnancy / perinatal status","Create a death notification flagged maternal/perinatal","Notify the district MPDSR committee","Schedule a verbal autopsy / family interview"]'::jsonb, (SELECT user_id FROM users WHERE email = 't.moyo@mohcc.org.zw'))
  ON CONFLICT (playbook_id) DO NOTHING;
INSERT INTO response_playbooks (playbook_id, name, description, signal_type, steps, created_by)
  VALUES ('ffbd3049-0408-48d8-8181-0f6ecc3f93a5', 'Unreported death follow-up', 'Trace community deaths that were never formally notified and complete registration.', 'unreported_death', '["Visit the household or contact the informant","Collect the deceased''s identity details","Create a death notification at the nearest facility","Record cause of death via verbal autopsy if needed","Close the signal once the notification is filed"]'::jsonb, (SELECT user_id FROM users WHERE email = 't.moyo@mohcc.org.zw'))
  ON CONFLICT (playbook_id) DO NOTHING;

