-- Outbreak alert for the seeded cholera cluster (what detectOutbreaks() would create)
INSERT INTO outbreak_alerts
  (alert_id, disease_category, district, cluster_data, case_count, risk_score, alert_type, dispatched_channels)
  SELECT 'b66b0982-cd74-48ff-ae95-1cc0fea9c712', 'Infectious - Waterborne', 'Harare', '{"window_hours":48,"detection":"seed","note":"12-case cholera cluster seeded for TC-04"}'::jsonb, 12, 100, 'outbreak', 'dashboard,audit-log'
  WHERE NOT EXISTS (SELECT 1 FROM outbreak_alerts WHERE status = 'active' AND district = 'Harare' AND disease_category = 'Infectious - Waterborne' AND alert_type = 'outbreak');

COMMIT;